<?php require 'includes/config.php';$pageTitle='Login';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare("SELECT * FROM users WHERE email=?");$st->execute([$_POST['email']]);$u=$st->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email']];header('Location: account.php');exit;}$error='Invalid email or password.';}include 'includes/header.php';?>
